import{_ as o,o as r,c as t,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Scaling CephFS MDS for Front Developer Workspaces on Kubernetes","description":"","frontmatter":{"title":"Scaling CephFS MDS for Front Developer Workspaces on Kubernetes","outline":"deep"},"headers":[],"relativePath":"posts/2026/Scaling_CephFS_MDS_for_Front_Developer_Workspaces_on_Kubernetes.md","filePath":"posts/2026/Scaling_CephFS_MDS_for_Front_Developer_Workspaces_on_Kubernetes.md","lastUpdated":null}'),s={name:"posts/2026/Scaling_CephFS_MDS_for_Front_Developer_Workspaces_on_Kubernetes.md"};function a(l,e,i,g,p,c){return r(),t("div",null,[...e[0]||(e[0]=[n('<p>I&#39;m drafting a comprehensive Chinese meeting summary about scaling CephFS MDS for developer workspaces on Kubernetes at Inditex, and selecting relevant tags like CephFS, MDS, Kubernetes, Rook, performance optimization, and OSD.--- title: Scaling CephFS MDS for Front Developer Workspaces on Kubernetes date: 2026-07-10 updated: 2026-07-10 tags:</p><ul><li>CephFS</li><li>MDS</li><li>Kubernetes</li><li>Rook</li><li>性能优化 categories:</li><li>视频总结 subtitle: Scaling_CephFS_MDS_for_Front_Developer_Workspaces_on_Kubernetes</li></ul><hr><h2 id="背景介绍" tabindex="-1">背景介绍 <a class="header-anchor" href="#背景介绍" aria-label="Permalink to &quot;背景介绍&quot;">​</a></h2><p>本次分享由 Inditex 平台团队的 Ismael 主讲，他在该公司已工作十余年。Inditex 是一家拥有 50 余年历史的时尚集团，旗下拥有 Zara、Massimo Dutti、Bershka 等八个品牌，业务覆盖 200 个市场，运营超过 5000 家门店。集团的技术团队规模庞大，拥有 1000 多个技术团队，每年完成超过一百万次部署，其中约五分之一面向生产环境。</p><p>演讲者所在的平台团队(Platform Team)承担着一项核心职责: 为开发者提供最佳的开发体验。在他们的责任模型下,开发者只需专注于编写代码,而平台团队则负责提供框架、持续部署(continuous deployment)、监控(monitoring)以及底层基础设施。当开发者需要创建应用时,只需提交一份简单的 YAML,平台便会据此生成部署应用所需的各类对象,团队为基础设施中的每个组件都构建了抽象层。</p><h2 id="技术演进历程" tabindex="-1">技术演进历程 <a class="header-anchor" href="#技术演进历程" aria-label="Permalink to &quot;技术演进历程&quot;">​</a></h2><p>团队的存储技术栈经历了多次迭代:</p><ul><li>2018 年从 <strong>Ceph</strong> Luminous 版本起步,使用 RPM 部署,搭配 <strong>FileStore</strong> 后端,速度虽慢但基本可用</li><li>随后迁移到容器化方案,先采用早期容器运行时,后迁移至 Podman</li><li>最终演进到在 <strong>Kubernetes</strong> 上运行</li></ul><h2 id="解决方案架构" tabindex="-1">解决方案架构 <a class="header-anchor" href="#解决方案架构" aria-label="Permalink to &quot;解决方案架构&quot;">​</a></h2><p>演讲聚焦于为前端开发者提供的工作空间(workspace)平台。该平台由两部分组成: 左侧是基于简单 prompt 生成前端页面的 agent,右侧是运行在 <strong>Kubernetes</strong> 上、通过 workspace operator 提供开发者体验并管理存储的机制。</p><p>在设计应用时,团队遵循四项原则:</p><ol><li><strong>Kubernetes ready</strong> —— 以 <strong>Kubernetes</strong> 作为统一部署语言</li><li><strong>Scalable(可扩展)</strong> —— 确保应用能在其规模下正常运行</li><li><strong>Portable(可移植)</strong> —— 应用可在 on-premise 与 cloud 等不同 <strong>Kubernetes</strong> 环境间迁移</li><li><strong>Infrastructure agnostic(基础设施无关)</strong> —— 避免 vendor locking(厂商锁定)</li></ol><p>存储方案选择了 <strong>Ceph</strong> 配合 <strong>Rook</strong>。选用 <strong>Rook</strong> 的原因在于: 不同云厂商(如 AWS、GCP)提供的文件系统存储体验各异,而 <strong>Rook</strong> 作为 <strong>Kubernetes</strong> 中的 operator,能以声明式(declarative)方式部署、管理和扩展 <strong>Ceph</strong>,从而在各类环境中提供一致的存储体验。</p><p>工作空间的运作流程: 每个 workspace 是为单个开发者独立分配的空间。创建新工作空间时,workspace manager 会将基础模板(base template)复制到 PV(Persistent Volume),新 Pod 挂载该 PV 后完成环境配置、GitHub 账号设置、依赖安装。由于这是 Node 应用,安装依赖属于重 IOPS 操作。最后通过 HMR(Hot Module Replacement,热模块替换)唤醒节点。若开发者后续需要安装新依赖,流程会重新回到依赖安装环节。PV 内容包含成千上万个 workspace,以及一个供项目内所有 workspace 共享的 global store 全局仓库目录。</p><h2 id="遇到的问题与瓶颈" tabindex="-1">遇到的问题与瓶颈 <a class="header-anchor" href="#遇到的问题与瓶颈" aria-label="Permalink to &quot;遇到的问题与瓶颈&quot;">​</a></h2><p>团队最初的 <strong>Rook</strong> 部署栈非常精简: 3 个 <strong>OSD</strong>、1 个 <strong>MDS</strong>(metadata server)、2 个 manager、1 个 monitor,足迹很小,但完全不具备生产就绪能力。随着平台从 2020 个工作空间起步进行扩容,一系列问题逐渐暴露-</p><p><strong>1. SELinux 进程限制</strong></p><p>在启用了 SELinux 支持的发行版上,每个容器都需确保安全标签(label)与预期匹配。空 Pod 启动没有问题,但当 PV 中包含上百万文件时,SELinux 需要重新标记(relabel)每一个文件,导致启动时间极长。</p><p><strong>2. MDS 慢请求(slow request)瓶颈</strong></p><p>由于最初只有单个 <strong>MDS</strong>,扩容后立刻出现了 MDS slow request 告警,MDS 的 CPU 占用飙升至顶峰。通过 <code>perf</code> 等命令可以获取大量诊断信息。在扩容后的头 30 分钟内,团队观测到惊人的请求量: 约 42 次 link 操作、30000 次 lookup、9000 次 create,累计在五分钟内产生了 <strong>3700 万次元数据请求</strong>。</p><p><strong>3. npm 依赖模型问题</strong></p><p>npm install 会为每个模块创建新文件,给 <strong>MDS</strong> 带来巨大压力。团队改用类仓库(repository)方式,通过 hard link(硬链接)复用文件,因为硬链接对 <strong>MDS</strong> 的负担更小 —— 无需创建新文件,只需创建链接。</p><p><strong>4. 缓存(cache)导致的延迟自我 DDoS</strong></p><p><strong>Ceph</strong> 中缺少直接的 cache 相关指标,但经验表明延迟长时间升高往往与 cache 有关。当 <strong>MDS</strong> 变慢(表现为 MDS client recall)时,进程无法在 5 分钟内完成启动,便会被 kill 后重启,形成了在存储平台上的&quot;自我 DDoS&quot;效应。</p><h2 id="扩容-scale-up-解决方案" tabindex="-1">扩容(Scale Up)解决方案 <a class="header-anchor" href="#扩容-scale-up-解决方案" aria-label="Permalink to &quot;扩容(Scale Up)解决方案&quot;">​</a></h2><p>针对上述问题,团队采取了以下措施:</p><ul><li><strong>跳过 SELinux 全量重标记</strong>: 通过配置让 SELinux 只检查根目录标签是否符合预期,而不逐一 relabel 每个文件。这样即便 PV 中有上千万文件,启动也能在数秒内完成</li><li><strong>增大元数据缓存(metadata cache)</strong>: 此项需在 <strong>Ceph</strong> 侧执行,<strong>Kubernetes</strong> 侧无对应机制</li><li><strong>扩展 MDS</strong>: 最终确定 70 个 active <strong>MDS</strong> 为合适数量,同时提升其 CPU 与内存,该操作可从 <strong>Kubernetes</strong> 侧完成</li><li><strong>扩展 OSD</strong>: <strong>OSD</strong> 数量从 3 个增加到 27 个,以在存储层实现并行化,这与扩展 <strong>MDS</strong> 同等重要</li><li><strong>手动 pinning(固定)</strong>: 由于 rebalance 无法正确工作,需要将 sub volume 手动 pin 到特定 <strong>MDS</strong>。这一过程无法自动扩展,必须手动创建,但已是团队找到的最佳方案,该命令同样需从 <strong>Ceph</strong> 侧执行</li></ul><p>最终测试中,集群健康状态良好: 约 3200 万个对象,zero slow reply,capability(cap)峰值达到 32000。</p><h2 id="pv-拆分与隔离" tabindex="-1">PV 拆分与隔离 <a class="header-anchor" href="#pv-拆分与隔离" aria-label="Permalink to &quot;PV 拆分与隔离&quot;">​</a></h2><p>对于新的工作空间流程,团队引入了 PV 拆分: workspace manager 管理约 16 个 PV,为新工作空间分配特定 PV,并仅挂载 work 文件夹和 global store 两个目录。这种方式实现了当前至关重要的<strong>项目隔离(isolation)</strong>。代价是需要在 16 个 PV 之间复制信息。</p><p>同时,可观测性(observability)是成功的关键。团队将指标提取到外部系统(如 Victoria Metrics),以便将业务活动与存储表现关联分析。例如周一早晨或内部培训期间,<strong>MDS</strong> 的使用量会随之上升。</p><h2 id="遗留的开放问题" tabindex="-1">遗留的开放问题 <a class="header-anchor" href="#遗留的开放问题" aria-label="Permalink to &quot;遗留的开放问题&quot;">​</a></h2><ul><li><strong>内存成本过高</strong>: 当前需要 200GB 内存,团队认为偏高</li><li><strong>手动 pinning</strong>: 需向管理员申请操作,无法自动化</li><li><strong>负载分布不均</strong>: 若多个重度用户集中在同一 PV,会造成分布不均</li><li><strong>生态尚不成熟</strong>: 相关生态持续演进但尚未就绪,DaemonSet 挂载存储的时机也存在问题</li><li><strong>夜间存储伸缩</strong>: 夜间流量低时希望能缩减存储资源</li></ul><h2 id="关键经验总结" tabindex="-1">关键经验总结 <a class="header-anchor" href="#关键经验总结" aria-label="Permalink to &quot;关键经验总结&quot;">​</a></h2><p>演讲者总结了本次旅程中习得的主要经验:</p><ol><li><strong>生产前先规划扩容</strong> —— <strong>Rook</strong> 默认配置并非生产就绪,需要投入时间做好准备</li><li><strong>不要盲目信任 balancer</strong> —— 团队发现 sub volume 必须依赖 pinning</li><li><strong>扩展整个技术栈</strong> —— 团队起初只关注 <strong>MDS</strong>,但缓存同样需要扩展,否则会增加延迟</li><li><strong>始终重视可观测性</strong> —— 它是成功的关键</li></ol><p>演讲最后指出,项目相关代码已发布在团队的 GitHub 仓库中。</p><h2 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h2><ul><li>持续优化内存占用,降低当前 200GB 的高内存成本</li><li>探索 sub volume 自动 pinning 机制,减少对管理员的手动依赖</li><li>改进负载分布,避免重度用户集中导致的不均衡</li><li>跟进生态成熟度,完善 DaemonSet 存储挂载时机</li><li>研究夜间存储资源的弹性缩减方案</li></ul>',40)])])}const S=o(s,[["render",a]]);export{h as __pageData,S as default};
